import {
  Container,
  Typography,
  Card,
  CardMedia,
  CircularProgress,
  Chip,
  Box,
} from "@mui/material";

import { useParams } from "react-router-dom";

import { useEffect, useState } from "react";

import API from "../services/api";

export default function BlogDetails() {
  const { id } = useParams();

  const [blog, setBlog] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchBlog = async () => {
      try {
        const response = await API.get(
          `/blogs/${id}`
        );

        setBlog(response.data);
      }
      catch (error) {
        console.log(eror);
      }
      finally {
        setLoading(false);
      }
    };

    fetchBlog();
  }, [id]);

  if (loading) {
    return (
      <Container sx={{ py: 5 }}>
        <CircularProgress />
      </Container>
    );
  }

  if(!blog){
    return(
      <Container sx={{py:5}}>
        <Typography>
          Blog not found!
        </Typography>
      </Container>
    );
  }
return (
    <Container maxWidth="md" sx={{ py: 5 }}>

      <Card
        sx={{
          borderRadius: 4,
          overflow: "hidden",
        }}
      >

        <CardMedia
          component="img"
          height="400"
          image={blog.image}
          alt={blog.title}
        />

        <Box sx={{ p: 4 }}>

          <Chip
            label={blog.category}
            color="primary"
            sx={{ mb: 2 }}
          />

          <Typography
            variant="h3"
            fontWeight={700}
            gutterBottom
          >
            {blog.title}
          </Typography>

          <Typography
            variant="body1"
            color="text.secondary"
            sx={{
              lineHeight: 2,
              mt: 3,
            }}
          >
            {blog.content}
          </Typography>

        </Box>

      </Card>

    </Container>
  );
}
